#branch-banner {
    position: fixed;
    left: 0; right: 0;
    top: 0;
}

animation.css:
.branch-banner-enter {
    animation: branch-slide-in-top 0.25s ease both;
}
@keyframes branch-slide-in-top { from { transform: translateY(-100%); } to { transform: translate(0); } }
.branch-banner-exit {
    animation: branch-slide-out-top 0.25s ease both;
}
@keyframes branch-slide-out-top { from { transform: translate(0); } to { transform: translateY(-100%); } }
